"""Production vendor volume hooks: exact row identity, native draw once, restoration."""
from pathlib import Path
import ast,subprocess,tempfile
root=Path(__file__).resolve().parents[1]
module=ast.parse((root/'tests/test_brightness_backend.py').read_text())
namespace={'__file__':str(root/'tests/test_brightness_backend.py')}
exec(compile(ast.Module(body=[n for n in module.body if not isinstance(n,ast.With)],type_ignores=[]),'brightness-doubles','exec'),namespace)
sources={k:v for k,v in namespace['sources'].items() if not k.endswith('BrightnessTest.java')}
sources['de/robv/android/xposed/XposedHelpers.java']=sources['de/robv/android/xposed/XposedHelpers.java'].replace('public class XposedHelpers {','public class XposedHelpers {public static Object getObjectField(Object o,String name){try{for(Class<?> c=o.getClass();c!=null;c=c.getSuperclass())try{var f=c.getDeclaredField(name);f.setAccessible(true);return f.get(o);}catch(NoSuchFieldException absent){}throw new IllegalStateException();}catch(ReflectiveOperationException e){throw new RuntimeException(e);}}')
sources.update({
'android/graphics/RectF.java':'package android.graphics;public class RectF {public RectF(float l,float t,float r,float b){}}',
'com/elitedarkkaiser/nubialy/VolumeEffects.java':'package com.elitedarkkaiser.nubialy;public class VolumeEffects {public static int decorated;public static boolean draw(int style,android.graphics.Canvas c,android.graphics.RectF b,float[] radii,float density,java.util.function.BooleanSupplier allowed,QsOutlineRenderer.NativeDraw stock)throws Throwable {if(!allowed.getAsBoolean())return false;stock.draw();if(!allowed.getAsBoolean())return false;decorated++;return true;}}',
'com/zte/mifavor/widget/ColorSeekBarZTE.java':'''package com.zte.mifavor.widget;import android.graphics.Canvas;import de.robv.android.xposed.XposedBridge;public class ColorSeekBarZTE extends android.widget.SeekBar {public int mLeftPadding=0,mTopPadding=0,mLength=120,mTrackSize=40;public float[] mRadii=new float[8];public void onDraw(Canvas c){Runnable stock=()->{if(c.failOnce){c.failOnce=false;throw new IllegalStateException();}c.draws++;if(c.during!=null)c.during.run();};if(XposedBridge.bypass)stock.run();else XposedBridge.run(this,ColorSeekBarZTE.class,"onDraw",new Class<?>[]{Canvas.class},new Object[]{c},stock);}}''',
'com/android/systemui/volume/VolumeDialogImpl.java':'''package com.android.systemui.volume;public class VolumeDialogImpl {public java.util.List<VolumeRow> mRows=new java.util.ArrayList<>();public static class VolumeRow {public android.widget.SeekBar slider=new com.zte.mifavor.widget.ColorSeekBarZTE();public android.view.View view=new android.view.View();public VolumeRow(){slider.parent=view;}}}''',
'com/zte/feature/volume/MfvVolumeDialogImpl.java':'''package com.zte.feature.volume;import de.robv.android.xposed.XposedBridge;import com.android.systemui.volume.VolumeDialogImpl;public class MfvVolumeDialogImpl extends VolumeDialogImpl {public void initRow(VolumeRow row,int a,int b,int c,boolean d,boolean e){XposedBridge.run(this,MfvVolumeDialogImpl.class,"initRow",new Class<?>[]{VolumeRow.class,int.class,int.class,int.class,boolean.class,boolean.class},new Object[]{row,a,b,c,d,e},()->{if(!mRows.contains(row))mRows.add(row);});}public void showH(int a,boolean b,int c){XposedBridge.run(this,MfvVolumeDialogImpl.class,"showH",new Class<?>[]{int.class,boolean.class,int.class},new Object[]{a,b,c},()->{});}}''',
'com/elitedarkkaiser/nubialy/xposed/VolumeTest.java':'''package com.elitedarkkaiser.nubialy.xposed;import android.graphics.*;import com.elitedarkkaiser.nubialy.VolumeEffects;public class VolumeTest {static void check(boolean b){if(!b)throw new AssertionError(VolumeBackend.status());}public static void main(String[] args){VolumeBackend.install(VolumeTest.class.getClassLoader());var dialog=new com.zte.feature.volume.MfvVolumeDialogImpl();var row=new com.android.systemui.volume.VolumeDialogImpl.VolumeRow();dialog.initRow(row,3,0,0,true,false);var slider=(com.zte.mifavor.widget.ColorSeekBarZTE)row.slider;
for(int style=1;style<=6;style++){VolumeBackend.begin(style);VolumeEffects.decorated=0;Canvas c=new Canvas();slider.onDraw(c);check(c.draws==1&&VolumeEffects.decorated==1);new com.zte.mifavor.widget.ColorSeekBarZTE().onDraw(new Canvas());check(VolumeEffects.decorated==1);slider.attached=false;slider.onDraw(new Canvas());check(VolumeEffects.decorated==1);slider.attached=true;android.os.Looper.off=true;slider.onDraw(new Canvas());check(VolumeEffects.decorated==1);android.os.Looper.off=false;
var parent=slider.parent;slider.parent=new android.view.View();slider.onDraw(new Canvas());check(VolumeEffects.decorated==1);slider.parent=parent;dialog.mRows.clear();slider.onDraw(new Canvas());check(VolumeEffects.decorated==1);dialog.mRows.add(row);var replacement=new com.zte.mifavor.widget.ColorSeekBarZTE();replacement.parent=row.view;row.slider=replacement;slider.onDraw(new Canvas());check(VolumeEffects.decorated==1);dialog.showH(0,false,0);replacement.onDraw(new Canvas());check(VolumeEffects.decorated==2);row.slider=slider;VolumeBackend.refresh();check(VolumeBackend.end());slider.onDraw(new Canvas());check(VolumeEffects.decorated==2);}
VolumeBackend.begin(1);Canvas c=new Canvas();c.during=()->VolumeBackend.end();slider.onDraw(c);check(VolumeBackend.healthy());check(VolumeBackend.end());VolumeBackend.begin(1);c=new Canvas();c.failOnce=true;slider.onDraw(c);check(!VolumeBackend.healthy());check(VolumeBackend.end());System.out.println("Volume exact ownership, native draw once, stream row membership, replacement, detach, thread, revocation, failure and restoration passed");}}'''
})
with tempfile.TemporaryDirectory(prefix='nubialy-volume-') as folder:
 folder=Path(folder)
 for name,content in sources.items():
  p=folder/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)
 files=[str(p) for p in folder.rglob('*.java')]+[str(root/'app/src/main/java/com/elitedarkkaiser/nubialy/xposed/VolumeBackend.java')]
 subprocess.run(['java','com.sun.tools.javac.Main','-d',str(folder/'classes'),*files],check=True)
 subprocess.run(['java','-cp',str(folder/'classes'),'com.elitedarkkaiser.nubialy.xposed.VolumeTest'],check=True)
